From 5ce7d2f890a2cdad6d5249e299037e46841d4223 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sun, 22 Nov 2026 00:31:13 +0100
Subject: [PATCH] kded: Only let the default device break global mute

Any change on any device broke global mute, even the sound server
restoring a newly plugged device's volume. Only the default device that
was there before breaks it now; other devices, mics too, stay muted.

BUG: 511576
---
 src/kded/audioshortcutsservice.cpp | 55 ++++++++++++++++++++++++++----
 src/kded/audioshortcutsservice.h   |  5 +++
 2 files changed, 54 insertions(+), 6 deletions(-)

diff --git a/src/kded/audioshortcutsservice.cpp b/src/kded/audioshortcutsservice.cpp
index b7e42fa2..48bcdd07 100644
--- a/src/kded/audioshortcutsservice.cpp
+++ b/src/kded/audioshortcutsservice.cpp
@@ -240,6 +240,14 @@ int AudioShortcutsService::changeVolumePercent(PulseAudioQt::Device *device, int
     const int maxVolume = PulseAudioQt::normalVolume() * (m_globalConfig->raiseMaximumVolume() ? 150 : 100) / 100.0;
     const qint64 newVolume = boundVolume(std::round(PulseAudioQt::normalVolume() * (targetPercent / 100.f)), maxVolume);
     const int newPercent = volumePercent(newVolume);
+
+    // A change made with the volume keys always comes from the user
+    if (qobject_cast<PulseAudioQt::Sink *>(device)) {
+        m_newSinks.remove(device->name());
+    } else {
+        m_newSources.remove(device->name());
+    }
+
     device->setMuted(newPercent == 0);
     device->setVolume(newVolume);
     return newPercent;
@@ -451,7 +459,11 @@ void AudioShortcutsService::handleNewSink(const QModelIndex &parent, int first,
     const bool globalMute = m_globalConfig->globalMuteSinks();

     for (int i = first; i <= last; ++i) {
-        applyGlobalSinkMute(m_sinkModel->index(i, 0), globalMute, globalMuteMutedDevices);
+        const auto index = m_sinkModel->index(i, 0);
+        if (globalMute && !m_sinkModel->data(index, m_sinkModel->role("Muted"_ba)).toBool()) {
+            m_newSinks.insert(m_sinkModel->data(index, m_sinkModel->role("Name"_ba)).toString());
+        }
+        applyGlobalSinkMute(index, globalMute, globalMuteMutedDevices);
     }

     m_globalConfig->setGlobalMuteSinksMutedDevices(globalMuteMutedDevices);
@@ -466,7 +478,11 @@ void AudioShortcutsService::handleNewSource(const QModelIndex &parent, int first
     const bool globalMicMute = m_globalConfig->globalMuteSources();

     for (int i = first; i <= last; ++i) {
-        applyGlobalSourceMute(m_sinkModel->index(i, 0), globalMicMute, globalMicMuteMutedDevices);
+        const auto index = m_sourceModel->index(i, 0);
+        if (globalMicMute && !m_sourceModel->data(index, m_sourceModel->role("Muted"_ba)).toBool()) {
+            m_newSources.insert(m_sourceModel->data(index, m_sourceModel->role("Name"_ba)).toString());
+        }
+        applyGlobalSourceMute(index, globalMicMute, globalMicMuteMutedDevices);
     }

     m_globalConfig->setGlobalMuteSourcesMutedDevices(globalMicMuteMutedDevices);
@@ -485,16 +501,27 @@ void AudioShortcutsService::handleSinkDataChanged(const QModelIndex &topLeft, co
         const bool volumeChanged = roles.contains(m_sinkModel->role("Volume"_ba));
         const bool mutedChanged = roles.contains(m_sinkModel->role("Muted"_ba));
         const bool isUnmuted = !m_sinkModel->data(index, m_sinkModel->role("Muted"_ba)).toBool();
+        const bool isDefault = m_sinkModel->data(index, m_sinkModel->role("Default"_ba)).toBool();
+        const QString name = m_sinkModel->data(index, m_sinkModel->role("Name"_ba)).toString();

         if (activePortIndexChanged) {
             // Apply global mute to new device
+            if (globalMute && isUnmuted) {
+                m_newSinks.insert(name);
+            }
             applyGlobalSinkMute(index, globalMute, globalMuteMutedDevices);

             m_globalConfig->setGlobalMuteSinksMutedDevices(globalMuteMutedDevices);
             m_globalConfig->save();
-        } else if (globalMute && (volumeChanged || (mutedChanged && isUnmuted))) {
-            // Changes to volume or unmuting break global mute
+        } else if (globalMute && isDefault && !m_newSinks.contains(name) && (volumeChanged || (mutedChanged && isUnmuted))) {
+            // Changes to volume or unmuting of the default device break global mute
             disableGlobalSinkMute();
+        } else if (globalMute && mutedChanged && isUnmuted) {
+            // Other devices stay muted
+            applyGlobalSinkMute(index, globalMute, globalMuteMutedDevices);
+
+            m_globalConfig->setGlobalMuteSinksMutedDevices(globalMuteMutedDevices);
+            m_globalConfig->save();
         }
     }
 }
@@ -511,16 +538,27 @@ void AudioShortcutsService::handleSourceDataChanged(const QModelIndex &topLeft,
         const bool volumeChanged = roles.contains(m_sourceModel->role("Volume"_ba));
         const bool mutedChanged = roles.contains(m_sourceModel->role("Muted"_ba));
         const bool isUnmuted = !m_sourceModel->data(index, m_sourceModel->role("Muted"_ba)).toBool();
+        const bool isDefault = m_sourceModel->data(index, m_sourceModel->role("Default"_ba)).toBool();
+        const QString name = m_sourceModel->data(index, m_sourceModel->role("Name"_ba)).toString();

         if (activePortIndexChanged) {
             // Apply global mute to new device
+            if (globalMicMute && isUnmuted) {
+                m_newSources.insert(name);
+            }
             applyGlobalSourceMute(index, globalMicMute, globalMicMuteMutedDevices);

             m_globalConfig->setGlobalMuteSourcesMutedDevices(globalMicMuteMutedDevices);
             m_globalConfig->save();
-        } else if (globalMicMute && (volumeChanged || (mutedChanged && isUnmuted))) {
-            // Changes to volume or unmuting break global mute
+        } else if (globalMicMute && isDefault && !m_newSources.contains(name) && (volumeChanged || (mutedChanged && isUnmuted))) {
+            // Changes to volume or unmuting of the default device break global mute
             disableGlobalSourceMute();
+        } else if (globalMicMute && mutedChanged && isUnmuted) {
+            // Other devices stay muted
+            applyGlobalSourceMute(index, globalMicMute, globalMicMuteMutedDevices);
+
+            m_globalConfig->setGlobalMuteSourcesMutedDevices(globalMicMuteMutedDevices);
+            m_globalConfig->save();
         }
     }
 }
@@ -528,6 +566,7 @@ void AudioShortcutsService::handleSourceDataChanged(const QModelIndex &topLeft,
 void AudioShortcutsService::enableGlobalSinkMute()
 {
     QStringList globalMuteMutedDevices = m_globalConfig->globalMuteSinksMutedDevices();
+    m_newSinks.clear();
     for (int i = 0; i < m_sinkModel->rowCount(); ++i) {
         applyGlobalSinkMute(m_sinkModel->index(i, 0), true, globalMuteMutedDevices);
     }
@@ -542,6 +581,7 @@ void AudioShortcutsService::enableGlobalSinkMute()
 void AudioShortcutsService::enableGlobalSourceMute()
 {
     QStringList globalMicMuteMutedDevices = m_globalConfig->globalMuteSourcesMutedDevices();
+    m_newSources.clear();
     for (int i = 0; i < m_sourceModel->rowCount(); ++i) {
         applyGlobalSourceMute(m_sourceModel->index(i, 0), true, globalMicMuteMutedDevices);
     }
@@ -556,6 +596,7 @@ void AudioShortcutsService::enableGlobalSourceMute()
 void AudioShortcutsService::disableGlobalSinkMute()
 {
     QStringList globalMuteMutedDevices = m_globalConfig->globalMuteSinksMutedDevices();
+    m_newSinks.clear();
     for (int i = 0; i < m_sinkModel->rowCount(); ++i) {
         applyGlobalSinkMute(m_sinkModel->index(i, 0), false, globalMuteMutedDevices);
     }
@@ -574,6 +615,7 @@ void AudioShortcutsService::disableGlobalSinkMute()
 void AudioShortcutsService::disableGlobalSourceMute()
 {
     QStringList globalMicMuteMutedDevices = m_globalConfig->globalMuteSourcesMutedDevices();
+    m_newSources.clear();
     for (int i = 0; i < m_sourceModel->rowCount(); ++i) {
         applyGlobalSourceMute(m_sourceModel->index(i, 0), false, globalMicMuteMutedDevices);
     }
@@ -590,6 +632,7 @@ void AudioShortcutsService::disableGlobalSourceMute()
 void AudioShortcutsService::pushToTalk(bool talk)
 {
     QStringList globalMicMuteMutedDevices = m_globalConfig->globalMuteSourcesMutedDevices();
+    m_newSources.clear();
     for (int i = 0; i < m_sourceModel->rowCount(); ++i) {
         applyGlobalSourceMute(m_sourceModel->index(i, 0), !talk, globalMicMuteMutedDevices);
     }
diff --git a/src/kded/audioshortcutsservice.h b/src/kded/audioshortcutsservice.h
index 26cf38d8..dfcafdc0 100644
--- a/src/kded/audioshortcutsservice.h
+++ b/src/kded/audioshortcutsservice.h
@@ -7,6 +7,8 @@

 #include <memory>

+#include <QSet>
+
 #include <KConfigWatcher>
 #include <kdedmodule.h>

@@ -86,5 +88,8 @@ private:
     PreferredDevice m_preferredDevice;
     QMetaObject::Connection m_preferredSinkVolumeConnection;
     std::unique_ptr<MutedMicrophoneReminder> m_mutedMicrophoneReminder;
+    // Devices that global mute had to mute when they appeared, which the sound server may still be restoring
+    QSet<QString> m_newSinks;
+    QSet<QString> m_newSources;
     KDBusPropertiesChangedAdaptor m_adaptor = {QStringLiteral("/modules/audioshortcutsservice"), this};
 };
-- 
